 useEffect(()=>{const refresh=e=>{if(e.detail.key===key)setItems(load(key))};window.addEventListener('desk-data-change',refresh);return()=>window.removeEventListener('desk-data-change',refresh)},[key]);
 const [status,setStatus]=useState('');const [deleteItem,setDeleteItem]=useState(null);const [busy,setBusy]=useState(false);const [dragged,setDragged]=useState(null);const [target,setTarget]=useState(null);const [editing,setEditing]=useState(null);const [cardSizes,setCardSizes]=useState(()=>{try{const saved=JSON.parse(localStorage.getItem('desk-card-sizes')||'{}');if(name==='任务'||name==='发现'){for(const k of Object.keys(saved))if(k.startsWith(name+':'))delete saved[k];localStorage.setItem('desk-card-sizes',JSON.stringify(saved))}return saved}catch{return {}}});
 const commit=next=>{save(key,next);setItems(next)};
 const isCategorized=name==='笔记'||name==='任务';
 const folderField=name==='任务'?'category':'folder';
 const storedFolders=name==='任务'?taskFolders:noteFolders;
 const folders=[...new Set([...storedFolders,...items.map(x=>x[folderField]||'未分类')])];
