 const createFolder=e=>{e.preventDefault();const folder=folderDraft.trim();if(!folder)return;if(folders.includes(folder))return setFolderError('该分类已存在');const next=[...storedFolders,folder];if(name==='任务'){setTaskFolders(next);localStorage.setItem('desk-task-folders',JSON.stringify(next))}else{setNoteFolders(next);localStorage.setItem('desk-note-folders',JSON.stringify(next))}setNoteFolder(folder);setFolderDraft(null)};

 const manageFolder=(action)=>{setFolderError('');setFolderDraft(action==='rename'?noteFolder:null);setFolderAction(action)};
 const submitFolderAction=e=>{e?.preventDefault();const original=noteFolder;const target=folderAction==='delete'?'未分类':folderDraft.trim();if(!target)return setFolderError('请输入分类名称');if(folderAction==='rename'&&target!==original&&folders.includes(target))return setFolderError('该分类已存在');
 commit(items.map(item=>(item[folderField]||'未分类')===original?{...item,[folderField]:target}:item));
 const next=[...new Set(storedFolders.map(folder=>folder===original?target:folder).filter(folder=>folder!=='未分类'))];if(folderAction==='rename'&&target!=='未分类'&&!next.includes(target))next.push(target);if(name==='任务'){setTaskFolders(next);localStorage.setItem('desk-task-folders',JSON.stringify(next))}else{setNoteFolders(next);localStorage.setItem('desk-note-folders',JSON.stringify(next));}
 if(folderAction==='rename'){setCardSizes(current=>{const next={...current},oldKey=`${name}:${discoverTab}:${original}`,newKey=`${name}:${discoverTab}:${target}`;if(next[oldKey]){next[newKey]=next[oldKey];delete next[oldKey];localStorage.setItem('desk-card-sizes',JSON.stringify(next))}return next})}
 setNoteFolder(folderAction==='delete'?'':target);setFolderAction(null);setFolderDraft(null);setFolderError('')};
 useEffect(()=>{if(folderDraft===null&&!folderAction)return;const handle=e=>{if(e.key==='Escape'){e.preventDefault();setFolderDraft(null);setFolderAction(null);setFolderError('')}else if(e.key==='Enter'&&folderAction==='delete'&&!e.repeat){e.preventDefault();submitFolderAction()}};window.addEventListener('keydown',handle);return()=>window.removeEventListener('keydown',handle)},[folderDraft,folderAction,noteFolder,items,noteFolders]);

 useEffect(()=>{if(!deleteItem)return;const onKey=e=>{if(e.key==='Escape'){setDeleteItem(null)}else if(e.key==='Enter'&&e.target.tagName!=='INPUT'&&e.target.tagName!=='TEXTAREA'){e.preventDefault();e.stopImmediatePropagation();commit(items.filter(x=>x.id!==deleteItem.id));setDeleteItem(null)}};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey)},[deleteItem,items]);
 const switchTab=tab=>{setDiscoverTab(tab);setItems(load(tab==='sources'?'sources':'discoveries'));setDragged(null);setTarget(null);setStatus('')};
 const change=(id,patch)=>{let next=items.map(x=>x.id===id?{...x,...patch}:x);const task=items.find(x=>x.id===id);if(name==='任务'&&task&&!task.done&&patch.done&&task.repeat&&task.repeat!=='不重复'){const base=new Date(task.date&&/^\d{4}-\d{2}-\d{2}$/.test(task.date)?`${task.date}T00:00:00`:Date.now());if(task.repeat==='每年')base.setFullYear(base.getFullYear()+1);else if(task.repeat==='每月')base.setMonth(base.getMonth()+1);else if(task.repeat==='每周')base.setDate(base.getDate()+7);else base.setDate(base.getDate()+1);next=[...next,{...task,id:crypto.randomUUID(),date:base.toISOString().slice(0,10),done:false}]};commit(next)};
 const itemCategory=item=>name==='任务'?(item.category||'未分类'):name==='笔记'?(item.folder||'未分类'):discoverTab==='sources'?(item.type||'未分类'):(item.source||'未分类');
 const setCategorySize=(category,dimensions)=>setCardSizes(current=>{const next={...current,[`${name}:${discoverTab}:${category}`]:dimensions};localStorage.setItem('desk-card-sizes',JSON.stringify(next));return next});
 const reorder=(fromId,toId)=>{const from=items.findIndex(x=>x.id===fromId),to=items.findIndex(x=>x.id===toId);if(from<0||to<0||from===to)return;const next=[...items];const [moved]=next.splice(from,1);next.splice(to,0,moved);commit(next);setStatus('排列顺序已保存')};
